import{_ as e,a,o as r,a6 as n}from"./chunks/framework.CJDy2q7X.js";const c=JSON.parse('{"title":"Start Import (GraphQL)","description":"","frontmatter":{"outline":false,"examples":[{"id":"gql","title":"Start Import","description":"Processes the next pending batch of rows. The field name follows API Platform naming — clients typically alias it. Runs against a validated import.","query":"mutation StartImport($input: startAdminSettingsDataTransferImportStartInput!) {\\n  startAdminSettingsDataTransferImportStart(input: $input) {\\n    adminSettingsDataTransferImportStart {\\n      _id\\n      state\\n      processedRowsCount\\n      invalidRowsCount\\n      errorsCount\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/settings/data-transfer/imports/12/start\\",\\n    \\"importId\\": 12\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"startAdminSettingsDataTransferImportStart\\": {\\n      \\"adminSettingsDataTransferImportStart\\": {\\n        \\"_id\\": 12,\\n        \\"state\\": \\"processing\\",\\n        \\"processedRowsCount\\": 10,\\n        \\"invalidRowsCount\\": 0,\\n        \\"errorsCount\\": 0\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/settings/data-transfer-imports/start.md","filePath":"api/graphql-api/admin/settings/data-transfer-imports/start.md","lastUpdated":1787725411000}'),o={name:"api/graphql-api/admin/settings/data-transfer-imports/start.md"};function i(s,t,d,p,l,h){return r(),a("div",null,t[0]||(t[0]=[n('<h1 id="start-import-graphql" tabindex="-1">Start Import (GraphQL) <a class="header-anchor" href="#start-import-graphql" aria-label="Permalink to &quot;Start Import (GraphQL)&quot;">​</a></h1><p>Processes the <strong>next pending batch</strong> of rows. Call it repeatedly — each call advances the import — until <a href="./stats.html">stats</a> reports <code>remaining: 0</code>. Runs only after the import has been <a href="./validate.html">validated</a>.</p><blockquote><p>This example runs against a <strong>validated, mid-pipeline</strong> import. A freshly-created import with validation errors returns <code>There is nothing to import.</code> instead.</p></blockquote><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>startAdminSettingsDataTransferImportStart</code></td><td>Mutation</td><td>Process the next batch of rows</td></tr></tbody></table><h2 id="after-processing" tabindex="-1">After processing <a class="header-anchor" href="#after-processing" aria-label="Permalink to &quot;After processing&quot;">​</a></h2><p>When all batches are processed, run the <a href="./link.html">link</a> stage, then the <a href="./">index</a> stage to finish the import.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>The mutation reports an error when there is nothing left to import, when the import has not been validated, or when asynchronous processing is requested but the queue is not configured.</p><h2 id="quirks" tabindex="-1">Quirks <a class="header-anchor" href="#quirks" aria-label="Permalink to &quot;Quirks&quot;">​</a></h2><ul><li>The input takes the import&#39;s <code>importId</code> <strong>and</strong> an <code>id</code> (the start IRI) — API Platform requires the <code>id</code> field on every non-create mutation.</li><li>Select <code>_id</code> for the numeric import id; the payload <code>id</code> IRI does not resolve on mutation results.</li></ul><p>The example uses an illustrative import. Replace it with a validated import in your store.</p><p>Permission: <code>settings.data_transfer.imports.edit</code>.</p>',13)]))}const u=e(o,[["render",i]]);export{c as __pageData,u as default};
